    56→
    57→
    58→def emit_mycelium_signal(signal: MyceliumSignal) -> None:
    59→    """Emit a signal to the Mycelium network (log-based interface).
    60→
    61→    Args:
    62→        signal: Signal to emit
    63→    """
    64→    logger.info(
    65→        f"Mycelium signal: {signal.event_type} "
    66→        f"scenarios={signal.scenario_count} agents={signal.agent_count} "
    67→        f"deltas={signal.capability_deltas}"
    68→    )
    69→    if signal.regressions:
    70→        logger.warning(f"Capability regressions: {signal.regressions}")
