    73→@dataclass
    74→class TrainingReport:
    75→    """Report from a training pipeline run."""
    76→
    77→    scenarios_completed: int
    78→    scenarios_failed: int
    79→    agents_evaluated: int
    80→    agent_profiles: dict[str, CapabilityProfile]
