    86→class UniverseTrainingPipeline:
    87→    """End-to-end agentic training environment pipeline."""
    88→
    89→    def __init__(self, config: TrainingConfig | None = None) -> None:
    90→        """Initialize pipeline with all components.
    91→
    92→        Args:
    93→            config: Training configuration (uses defaults if None)
    94→        """
    95→        self.config = config or TrainingConfig()
    96→        self.rng = random.Random(self.config.seed)
    97→        self.generator = ScenarioGenerator(seed=self.config.seed)
    98→        self.dispatcher = NexusScenarioDispatcher()
    99→        self.navigator = BioelectricNavigator()
   100→        self.encoder = VAEJourneyEncoder()
   101→        self.evaluator = CapabilityEvaluator()
   102→
   103→        # Use temp dir for recorder to avoid polluting data/
   104→        self._recorder_dir = tempfile.mkdtemp(prefix="ouroboros_")
   105→        self.recorder = OuroborosRecorder(data_dir=self._recorder_dir)
   106→
   107→    def run(self) -> TrainingReport:
   108→        """Execute complete training pipeline.
   109→
   110→        Returns:
   111→            TrainingReport with results
   112→        """
   113→        # 1. Generate scenarios (cycle through types)
   114→        scenario_types = list(ScenarioType)
   115→        scenarios = [
   116→            self.generator.generate(
   117→                self.rng.choice(scenario_types)
   118→            )
   119→            for _ in range(self.config.scenario_count)
   120→        ]
   121→
   122→        # 2. Create agents
   123→        agents = [
   124→            EVOAgent(agent_id=f"agent-{i}")
   125→            for i in range(self.config.agent_count)
   126→        ]
   127→
   128→        # 3. Start recording
   129→        recording_id = self.recorder.start_recording("training-run")
   130→
   131→        # 4. Execute scenarios in batches
   132→        all_scores: dict[str, list[CapabilityScore]] = {
   133→            a.agent_id: [] for a in agents
   134→        }
   135→        journey_embeddings: list[np.ndarray] = []
   136→        scenarios_completed = 0
   137→        scenarios_failed = 0
   138→
   139→        for batch_start in range(
   140→            0, len(scenarios), self.config.max_concurrent_scenarios
   141→        ):
   142→            batch = scenarios[
   143→                batch_start : batch_start + self.config.max_concurrent_scenarios
   144→            ]
   145→
   146→            for scenario in batch:
   147→                # Dispatch to fabric
   148→                dispatch_result = self.dispatcher.dispatch(scenario)
   149→
   150→                for agent in agents:
   151→                    try:
   152→                        # Navigate agent through scenario
   153→                        trajectory = self.navigator.navigate_scenario(
   154→                            scenario, agent, max_steps=self.config.max_steps
   155→                        )
   156→
   157→                        # Encode journey to 256D
   158→                        traj_obj = cast(list[dict[str, object]], trajectory)
   159→                        embedding = self.encoder.encode_trajectory_raw(
   160→                            traj_obj
   161→                        )
   162→                        journey_embeddings.append(embedding)
   163→
   164→                        # Evaluate capability
   165→                        journey_dicts = self._trajectory_to_journey(traj_obj)
   166→                        score = self.evaluator.evaluate(scenario, journey_dicts)
   167→                        all_scores[agent.agent_id].append(score)
   168→
   169→                        # Record to Ouroboros
   170→                        self.recorder.record_event(
   171→                            recording_id,
   172→                            event_type="scenario_complete",
   173→                            data={
   174→                                "agent": agent.agent_id,
   175→                                "fabric": dispatch_result.fabric,
   176→                                "scenario_type": scenario.type.value,
   177→                                "composite_score": score.composite(),
   178→                            },
   179→                        )
   180→
   181→                        scenarios_completed += 1
   182→
   183→                    except Exception as e:
   184→                        logger.warning(
   185→                            f"Scenario failed for {agent.agent_id}: {e}"
   186→                        )
   187→                        scenarios_failed += 1
   188→                        self.recorder.record_divergence(
   189→                            recording_id,
   190→                            divergence_type="scenario_failure",
   191→                            last_good_state={"agent": agent.agent_id},
   192→                            divergent_state={"error": str(e)},
   193→                        )
   194→
   195→                    # Reset agent for next scenario
   196→                    agent.state = agent.state.__class__()
   197→
   198→        # 5. Aggregate profiles
   199→        agent_profiles: dict[str, CapabilityProfile] = {}
   200→        for agent_id, scores in all_scores.items():
   201→            agent_profiles[agent_id] = CapabilityProfile.from_scores(scores)
   202→
   203→        # 6. Emit Mycelium signal
   204→        signal = MyceliumSignal(
   205→            event_type="pipeline_complete",
   206→            scenario_count=scenarios_completed,
   207→            agent_count=len(agents),
   208→            capability_deltas=self._compute_deltas(agent_profiles),
   209→        )
   210→        emit_mycelium_signal(signal)
   211→
   212→        return TrainingReport(
   213→            scenarios_completed=scenarios_completed,
   214→            scenarios_failed=scenarios_failed,
   215→            agents_evaluated=len(agents),
   216→            agent_profiles=agent_profiles,
   217→            journey_embeddings=journey_embeddings,
   218→            recording_id=recording_id,
   219→            mycelium_signal=signal,
   220→        )
