   222→    def find_similar_journeys(
   223→        self,
   224→        query: np.ndarray,
   225→        embeddings: list[np.ndarray],
   226→        top_k: int = 5,
   227→    ) -> list[tuple[int, float]]:
   228→        """Find similar journeys using cosine similarity.
   229→
   230→        Args:
   231→            query: Query embedding (256D)
   232→            embeddings: List of journey embeddings
   233→            top_k: Number of results to return
   234→
   235→        Returns:
   236→            List of (index, similarity) tuples sorted by similarity
   237→        """
   238→        similarities: list[tuple[int, float]] = []
   239→        query_norm = np.linalg.norm(query)
   240→        if query_norm == 0:
   241→            return []
   242→
   243→        for i, emb in enumerate(embeddings):
   244→            emb_norm = np.linalg.norm(emb)
   245→            if emb_norm == 0:
   246→                continue
   247→            sim = float(np.dot(query, emb) / (query_norm * emb_norm))
   248→            similarities.append((i, sim))
   249→
   250→        similarities.sort(key=lambda x: x[1], reverse=True)
   251→        return similarities[:top_k]
   252→
   253→    def _trajectory_to_journey(
   254→        self, trajectory: list[dict[str, object]]
   255→    ) -> list[dict[str, float]]:
   256→        """Convert navigator trajectory to evaluator journey format.
   257→
   258→        Args:
   259→            trajectory: List of trajectory points from BioelectricNavigator
   260→
   261→        Returns:
   262→            List of dicts with x, y, coherence keys for CapabilityEvaluator
   263→        """
   264→        journey: list[dict[str, float]] = []
   265→        for point in trajectory:
   266→            state = point.get("state")
   267→            if isinstance(state, np.ndarray):
   268→                journey.append(
   269→                    {
   270→                        "x": float(state[0]),
   271→                        "y": float(state[1]),
   272→                        "coherence": float(
   273→                            np.mean(state[4:11])
   274→                        ),  # HIHO dims average
   275→                    }
   276→                )
   277→            else:
   278→                journey.append({"x": 0.0, "y": 0.0, "coherence": 0.5})
   279→        return journey
   280→
   281→    def _compute_deltas(
   282→        self, profiles: dict[str, CapabilityProfile]
   283→    ) -> dict[str, float]:
   284→        """Compute capability deltas across agents.
   285→
   286→        Args:
   287→            profiles: Per-agent capability profiles
   288→
   289→        Returns:
   290→            Mean capability scores as deltas
   291→        """
   292→        if not profiles:
   293→            return {}
   294→
   295→        totals: dict[str, float] = {
   296→            "task_completion": 0.0,
   297→            "coherence_maintenance": 0.0,
   298→            "context_retention": 0.0,
   299→            "ambiguity_handling": 0.0,
   300→            "interruption_recovery": 0.0,
   301→            "judgment_quality": 0.0,
   302→        }
   303→
   304→        for profile in profiles.values():
   305→            totals["task_completion"] += profile.task_completion
   306→            totals["coherence_maintenance"] += profile.coherence_maintenance
   307→            totals["context_retention"] += profile.context_retention
   308→            totals["ambiguity_handling"] += profile.ambiguity_handling
   309→            totals["interruption_recovery"] += profile.interruption_recovery
   310→            totals["judgment_quality"] += profile.judgment_quality
   311→
   312→        n = len(profiles)
   313→        return {k: v / n for k, v in totals.items()}
   314→"}]},"uuid":"27114c4d-1595-4304-96af-566e44f70bb9","timestamp":"2026-02-19T04:31:29.794Z","sourceToolAssistantUUID":"e61cd59f-d25c-4b1a-adbc-02b8799b5a21"}
