   140→    def _evaluate_coherence(self, journey: list[dict[str, float]]) -> float:
   141→        """Evaluate coherence maintenance (HIHO stability at 0.5).
   142→
   143→        Args:
   144→            journey: Agent trajectory
   145→
   146→        Returns:
   147→            Coherence score (0.0-1.0)
