   160→    def _evaluate_context_retention(self, journey: list[dict[str, float]]) -> float:
   161→        """Evaluate context retention (path efficiency, not revisiting states).
   162→
   163→        Args:
   164→            journey: Agent trajectory
   165→
   166→        Returns:
   167→            Context retention score (0.0-1.0)
   168→        """
   169→        if len(journey) < 2:
   170→            return 0.5  # Neutral for very short journeys
   171→
   172→        # Measure path efficiency: total distance traveled vs direct distance
   173→        positions = [(point.get("x", 0.0), point.get("y", 0.0)) for point in journey]
   174→
   175→        # Total path length
   176→        total_distance = sum(
   177→            np.linalg.norm(np.array(positions[i + 1]) - np.array(positions[i]))
   178→            for i in range(len(positions) - 1)
   179→        )
   180→
   181→        # Direct distance (start to end)
   182→        direct_distance = np.linalg.norm(np.array(positions[-1]) - np.array(positions[0]))
   183→
   184→        if total_distance == 0:
   185→            return 0.0  # No movement
   186→
   187→        # Efficiency: direct / total (1.0 = perfectly straight path)
   188→        efficiency = direct_distance / total_distance if total_distance > 0 else 0.0
   189→
   190→        return float(min(1.0, efficiency))
