    48→    def start_recording(self, scenario_name: str) -> str:
    49→        """Start a new recording session.
    50→
    51→        Args:
    52→            scenario_name: Name/description of the scenario
    53→
    54→        Returns:
    55→            Recording ID for this session
    56→        """
    57→        recording_id = f"{scenario_name}_{uuid4().hex[:8]}"
    58→        logger.debug(f"Started recording: {recording_id}")
    59→        return recording_id
    60→
    61→    def record_event(
    62→        self,
    63→        recording_id: str,
