    77→                "event_type": event_type,
    78→                "timestamp": time.time(),
    79→                "data": data,
    80→            }
    81→
    82→            path = self._get_recording_path(recording_id)
    83→            self._check_rotation(path)
    84→
    85→            with open(path, "a") as f:
    86→                f.write(json.dumps(event) + "\n")
    87→        except Exception as e:
    88→            logger.warning(f"Recording failed (non-blocking): {e}")
