    90→    def record_divergence(
    91→        self,
    92→        recording_id: str,
    93→        divergence_type: str,
    94→        last_good_state: dict[str, object],
    95→        divergent_state: dict[str, object],
    96→    ) -> None:
    97→        """Record a divergence event for self-healing.
    98→
    99→        Args:
   100→            recording_id: Recording session ID
   101→            divergence_type: Type of divergence (coherence_collapse, nan, etc.)
   102→            last_good_state: Last known stable state
   103→            divergent_state: State where divergence occurred
   104→        """
   105→        self.record_event(
   106→            recording_id,
   107→            event_type="divergence",
   108→            data={
   109→                "divergence_type": divergence_type,
   110→                "last_good_state": last_good_state,
   111→                "divergent_state": divergent_state,
   112→            },
   113→        )
