   115→    def replay(self, recording_id: str) -> list[dict[str, object]]:
   116→        """Replay events from a recording.
   117→
   118→        Args:
   119→            recording_id: Recording session ID
   120→
   121→        Returns:
   122→            List of event dicts in chronological order
   123→        """
   124→        path = self._get_recording_path(recording_id)
   125→        if not path.exists():
   126→            return []
   127→
   128→        events: list[dict[str, object]] = []
   129→        try:
   130→            with open(path) as f:
   131→                for line in f:
